pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amt, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        amt = bound(amt, 1, 200000000e18);

        // owner (this test contract, the deployer) endows actor with a prior balance
        c.transfer(actor, amt);

        uint256 grant = c.value();
        assertTrue(grant > 0 && !c.blacklist(actor));

        // actor claims the airdrop exactly once
        vm.prank(actor);
        c.getTokens();

        // GENERAL RULE: the airdrop ADDS to any existing balance instead of
        // overwriting it: balanceOf(actor) == prior balance + granted value.
        assertTrue(c.balanceOf(actor) == amt + grant);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // admissible domain: a real recipient and a nonzero but affordable transfer
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        amount = bound(amount, 1, c.balanceOf(address(0)) + 1); // placeholder bound, replaced below
        // owner initializes balances via XBornID
        vm.prank(address(this));
        c.XBornID();
        amount = bound(amount, 1, c.balanceOf(address(this)));

        // owner funds the actor; the actor is not blacklisted yet
        vm.prank(address(this));
        c.transfer(actor, amount);

        uint256 grant = c.value();
        assertTrue(grant > 0);

        // the actor claims the airdrop
        vm.prank(actor);
        c.getTokens();

        // RULE: distribution accumulates onto the prior balance for every admissible input
        assertTrue(c.balanceOf(actor) == amount + grant);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test() public {
        c.XBornID();
        assert(c.balanceOf(address(this)) == c.totalDistributed());
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address from, address to) public {
        require(c.balanceOf(from) >= 100);
        uint256 amt = 100;

        // impersonation-free: 'from' approves this test contract via approve is called by msg.sender,
        // so we use the test contract itself as 'from' only if it holds balance; instead approve from caller.
        // Use c.approve as spender flow: msg.sender of test is this contract.
        require(c.balanceOf(address(this)) >= amt);

        c.approve(address(this), amt);
        c.transferFrom(address(this), to, amt);
        assert(c.allowance(address(this), address(this)) == 0);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address owner_) public payable {
        require(owner_ == address(this));
        c.XBornID();
        assert(c.balanceOf(owner_) == c.totalDistributed());
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _to, uint256 _amount) public {
        require(_amount > 0);
        // Setup: obtain tokens for address(this) via the airdrop, then self-approve.
        c.getTokens();
        c.approve(address(this), _amount);
        uint256 before = c.allowance(address(this), address(this));
        require(before == _amount);
        // Boundary call.
        c.transferFrom(address(this), _to, _amount);
        assert(c.allowance(address(this), address(this)) + _amount == before);
    }
    receive() external payable {}
}
